{
  "schemaVersion": "1.0.0",
  "workflowVersion": 1,
  "workflow": {
    "id": "wf-supervisor-worker-swarm",
    "name": "Supervisor + Worker Swarm",
    "description": "Multi-agent swarm pattern. A Supervisor coordinates two specialist Worker agents (a 'researcher' with MCP knowledge-base access and a 'computer' with calculator + time tools). Workers are exposed to the Supervisor as synthetic tools — the Supervisor decides which one to delegate each step to. Runs zero-key with the bundled echo provider and in-process mock-mcp adapter.",
    "schemaVersion": "1.0.0",
    "workflowVersion": 1,
    "nodes": [
      {
        "id": "trigger_1",
        "type": "manual_trigger",
        "name": "Manual Trigger",
        "position": { "x": 80, "y": 240 },
        "config": { "label": "Run swarm" }
      },
      {
        "id": "supervisor_1",
        "type": "supervisor_node",
        "name": "Supervisor",
        "position": { "x": 360, "y": 240 },
        "config": {
          "systemPromptTemplate": "You are a supervisor. Decompose the user request, delegate each subtask to the most appropriate specialist worker, and assemble a final answer. Workers: 'researcher' for knowledge-base lookups, 'computer' for math and time queries.",
          "userPromptTemplate": "{{user_prompt}}",
          "sessionIdTemplate": "swarm-demo",
          "maxIterations": 8
        }
      },
      {
        "id": "supervisor_chat",
        "type": "llm_call",
        "name": "Supervisor Chat Model (echo)",
        "position": { "x": 360, "y": 80 },
        "config": {
          "provider": { "providerId": "echo", "model": "demo", "prefix": "Supervisor: " },
          "promptKey": "prompt",
          "systemPromptKey": "system_prompt"
        }
      },
      {
        "id": "worker_research",
        "type": "agent_orchestrator",
        "name": "Worker: Researcher",
        "position": { "x": 660, "y": 380 },
        "config": {
          "systemPromptTemplate": "You answer factual questions by looking them up in the knowledge base via the lookup_kb MCP tool.",
          "userPromptTemplate": "{{user_prompt}}",
          "sessionIdTemplate": "swarm-demo:researcher",
          "maxIterations": 4,
          "toolCallingEnabled": true
        }
      },
      {
        "id": "worker_research_chat",
        "type": "llm_call",
        "name": "Researcher Chat (echo)",
        "position": { "x": 660, "y": 540 },
        "config": {
          "provider": { "providerId": "echo", "model": "demo", "prefix": "Researcher: " },
          "promptKey": "prompt",
          "systemPromptKey": "system_prompt"
        }
      },
      {
        "id": "worker_research_tool",
        "type": "mcp_tool",
        "name": "MCP: lookup_kb",
        "position": { "x": 860, "y": 540 },
        "config": {
          "serverId": "mock-mcp",
          "toolName": "lookup_kb",
          "argsTemplate": "{\"key\":\"mcp\"}",
          "connection": { "transport": "mock" }
        }
      },
      {
        "id": "worker_compute",
        "type": "agent_orchestrator",
        "name": "Worker: Computer",
        "position": { "x": 660, "y": 100 },
        "config": {
          "systemPromptTemplate": "You answer math and time questions by calling the calculator and get_current_time MCP tools.",
          "userPromptTemplate": "{{user_prompt}}",
          "sessionIdTemplate": "swarm-demo:computer",
          "maxIterations": 4,
          "toolCallingEnabled": true
        }
      },
      {
        "id": "worker_compute_chat",
        "type": "llm_call",
        "name": "Computer Chat (echo)",
        "position": { "x": 860, "y": 100 },
        "config": {
          "provider": { "providerId": "echo", "model": "demo", "prefix": "Computer: " },
          "promptKey": "prompt",
          "systemPromptKey": "system_prompt"
        }
      },
      {
        "id": "worker_compute_calc",
        "type": "mcp_tool",
        "name": "MCP: calculator",
        "position": { "x": 1060, "y": 60 },
        "config": {
          "serverId": "mock-mcp",
          "toolName": "calculator",
          "argsTemplate": "{\"expression\":\"2+2\"}",
          "connection": { "transport": "mock" }
        }
      },
      {
        "id": "worker_compute_time",
        "type": "mcp_tool",
        "name": "MCP: get_current_time",
        "position": { "x": 1060, "y": 160 },
        "config": {
          "serverId": "mock-mcp",
          "toolName": "get_current_time",
          "argsTemplate": "{\"tz\":\"UTC\"}",
          "connection": { "transport": "mock" }
        }
      },
      {
        "id": "output_1",
        "type": "output",
        "name": "Output",
        "position": { "x": 720, "y": 240 },
        "config": { "responseTemplate": "{{answer}}", "outputKey": "result" }
      }
    ],
    "edges": [
      { "id": "edge_main_1", "source": "trigger_1", "target": "supervisor_1" },
      { "id": "edge_main_2", "source": "supervisor_1", "target": "output_1" },
      { "id": "edge_sup_chat", "source": "supervisor_1", "sourceHandle": "chat_model", "target": "supervisor_chat" },
      { "id": "edge_sup_w_research", "source": "supervisor_1", "sourceHandle": "worker", "target": "worker_research" },
      { "id": "edge_sup_w_compute", "source": "supervisor_1", "sourceHandle": "worker", "target": "worker_compute" },
      { "id": "edge_research_chat", "source": "worker_research", "sourceHandle": "chat_model", "target": "worker_research_chat" },
      { "id": "edge_research_tool", "source": "worker_research", "sourceHandle": "tool", "target": "worker_research_tool" },
      { "id": "edge_compute_chat", "source": "worker_compute", "sourceHandle": "chat_model", "target": "worker_compute_chat" },
      { "id": "edge_compute_calc", "source": "worker_compute", "sourceHandle": "tool", "target": "worker_compute_calc" },
      { "id": "edge_compute_time", "source": "worker_compute", "sourceHandle": "tool", "target": "worker_compute_time" }
    ]
  },
  "exportedAt": "2026-05-07T00:00:00.000Z"
}

{
  "schemaVersion": "1.0.0",
  "workflowVersion": 1,
  "workflow": {
    "id": "wf-workflow-as-mcp-tool",
    "name": "Workflow as MCP Tool",
    "description": "Compose-by-MCP pattern. The mcp_server_trigger node turns this whole workflow into an MCP tool exposed at GET /api/mcp-server/kb-helper/manifest and POST /api/mcp-server/kb-helper/invoke. Other agents (in L2M, in your IDE, in other MCP-compatible runtimes) can wire 'kb-helper' in as a callable tool. Inside, the workflow runs an Agent that consults the bundled mock-mcp lookup_kb tool to answer the question. Demonstrates: agent -> workflow -> agent composition without any HTTP plumbing.",
    "schemaVersion": "1.0.0",
    "workflowVersion": 1,
    "nodes": [
      {
        "id": "mcp_trigger_1",
        "type": "mcp_server_trigger",
        "name": "Expose as MCP Tool",
        "position": { "x": 80, "y": 200 },
        "config": {
          "path": "kb-helper",
          "toolName": "answer_from_kb",
          "toolDescription": "Answer a question by looking it up in the L2M demo knowledge base.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "question": {
                "type": "string",
                "description": "Natural-language question to answer."
              }
            },
            "required": ["question"]
          },
          "authMode": "public"
        }
      },
      {
        "id": "agent_1",
        "type": "agent_orchestrator",
        "name": "Agent",
        "position": { "x": 380, "y": 200 },
        "config": {
          "systemPromptTemplate": "Answer the user's question by calling the lookup_kb MCP tool. Reply with a concise factual sentence.",
          "userPromptTemplate": "{{question}}",
          "sessionIdTemplate": "kb-helper",
          "maxIterations": 4,
          "toolCallingEnabled": true
        }
      },
      {
        "id": "llm_1",
        "type": "llm_call",
        "name": "Chat Model (echo)",
        "position": { "x": 440, "y": 380 },
        "config": {
          "provider": { "providerId": "echo", "model": "demo", "prefix": "Echo: " },
          "promptKey": "prompt",
          "systemPromptKey": "system_prompt"
        }
      },
      {
        "id": "tool_kb_1",
        "type": "mcp_tool",
        "name": "MCP: lookup_kb",
        "position": { "x": 660, "y": 380 },
        "config": {
          "serverId": "mock-mcp",
          "toolName": "lookup_kb",
          "argsTemplate": "{\"key\":\"mcp\"}",
          "connection": { "transport": "mock" }
        }
      },
      {
        "id": "output_1",
        "type": "output",
        "name": "Output",
        "position": { "x": 720, "y": 200 },
        "config": { "responseTemplate": "{{answer}}", "outputKey": "result" }
      }
    ],
    "edges": [
      { "id": "edge_main_1", "source": "mcp_trigger_1", "target": "agent_1" },
      { "id": "edge_main_2", "source": "agent_1", "target": "output_1" },
      { "id": "edge_aux_chat", "source": "agent_1", "sourceHandle": "chat_model", "target": "llm_1" },
      { "id": "edge_aux_tool", "source": "agent_1", "sourceHandle": "tool", "target": "tool_kb_1" }
    ]
  },
  "exportedAt": "2026-05-07T00:00:00.000Z"
}

{
  "schemaVersion": "1.0.0",
  "workflowVersion": 1,
  "workflow": {
    "id": "wf-rag-with-citations-flow",
    "name": "RAG with Citations",
    "description": "Text Input -> RAG Retrieve (KB) -> Prompt Template (with citation instructions) -> LLM -> Extract Citations -> Output. Demonstrates Phase 9.4 — every chunk retrieved by `rag_retrieve` carries stable provenance, the LLM is instructed to cite with [N] markers, and `extract_citations` resolves each marker back to the source chunk so the chat UI renders clickable footnotes. Replace `<your-kb-id>` with a real id from POST /api/knowledge-bases.",
    "schemaVersion": "1.0.0",
    "workflowVersion": 1,
    "nodes": [
      {
        "id": "text_1",
        "type": "text_input",
        "name": "Question",
        "position": { "x": 70, "y": 220 },
        "config": {
          "text": "How do I reset my password?"
        }
      },
      {
        "id": "rag_1",
        "type": "rag_retrieve",
        "name": "Retrieve",
        "position": { "x": 360, "y": 220 },
        "config": {
          "queryTemplate": "{{user_prompt}}",
          "topK": 4,
          "embedderId": "openai-embedder",
          "vectorStoreId": "knowledge-base",
          "vectorStoreConfig": {
            "knowledgeBaseId": "<your-kb-id>"
          },
          "searchMode": "hybrid"
        }
      },
      {
        "id": "template_1",
        "type": "prompt_template",
        "name": "Grounded Prompt",
        "position": { "x": 670, "y": 220 },
        "config": {
          "template": "Answer the question using only the context below.\n\n{{citationInstructions}}\n\nContext:\n{{context}}\n\nQuestion:\n{{user_prompt}}",
          "outputKey": "prompt"
        }
      },
      {
        "id": "llm_1",
        "type": "llm_call",
        "name": "LLM",
        "position": { "x": 980, "y": 220 },
        "config": {
          "provider": {
            "providerId": "openai",
            "model": "gpt-4o-mini",
            "temperature": 0.1
          },
          "promptKey": "prompt",
          "outputKey": "answer"
        }
      },
      {
        "id": "cite_1",
        "type": "extract_citations",
        "name": "Extract Citations",
        "position": { "x": 1290, "y": 220 },
        "config": {
          "answerPath": "answer",
          "documentsPath": "documents"
        }
      },
      {
        "id": "output_1",
        "type": "output",
        "name": "Output",
        "position": { "x": 1600, "y": 220 },
        "config": {
          "responseTemplate": "{{answer}}",
          "outputKey": "result"
        }
      }
    ],
    "edges": [
      { "id": "edge_1", "source": "text_1", "target": "rag_1" },
      { "id": "edge_2", "source": "rag_1", "target": "template_1" },
      { "id": "edge_3", "source": "text_1", "target": "template_1" },
      { "id": "edge_4", "source": "template_1", "target": "llm_1" },
      { "id": "edge_5", "source": "llm_1", "target": "cite_1" },
      { "id": "edge_6", "source": "rag_1", "target": "cite_1" },
      { "id": "edge_7", "source": "cite_1", "target": "output_1" }
    ]
  },
  "exportedAt": "2026-05-10T00:00:00.000Z"
}

